import java.util.Scanner;

public class Main {
    static int[] data;
    static int chunkSize;
    static long[] chunkSums;
    static long grandTotal = 0;

    static synchronized void merge(int index, long sum) {
        chunkSums[index] = sum;
        grandTotal = grandTotal + sum;
    }

    static class BatchTask implements Runnable {
        private int index;

        BatchTask(int index) {
            this.index = index;
        }

        public void run() {
            long s = 0;
            int start = index * chunkSize;
            for (int j = 0; j < chunkSize; j++) {
                s = s + data[start + j];
            }
            merge(index, s);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        chunkSize = sc.nextInt();
        int n = k * chunkSize;
        data = new int[n];
        for (int i = 0; i < n; i++) {
            data[i] = sc.nextInt();
        }
        chunkSums = new long[k];
        Thread[] workers = new Thread[k];
        for (int i = 0; i < k; i++) {
            workers[i] = new Thread(new BatchTask(i));
            workers[i].start();
        }
        for (int i = 0; i < k; i++) {
            workers[i].join();
        }
        for (int i = 0; i < k; i++) {
            System.out.println("Chunk " + (i + 1) + ": " + chunkSums[i]);
        }
        System.out.println("Grand total: " + grandTotal);
    }
}

