import java.util.Scanner;

public class Main {
    static int[] consumed;
    static int consumedCount;

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int cap = sc.nextInt();
        int k = sc.nextInt();
        int[] items = new int[k];
        for (int i = 0; i < k; i++) {
            items[i] = sc.nextInt();
        }
        consumed = new int[k];
        Buffer buffer = new Buffer(cap);
        Producer p = new Producer(buffer, items);
        Consumer c = new Consumer(buffer, k);
        c.start();
        p.start();
        p.join();
        c.join();
        for (int i = 0; i < k; i++) {
            System.out.println("Consumed: " + consumed[i]);
        }
        System.out.println("Total consumed: " + consumedCount);
    }
}

class Buffer {
    private int[] slots;
    private int count;
    private int head;
    private int tail;

    Buffer(int cap) {
        slots = new int[cap];
        count = 0;
        head = 0;
        tail = 0;
    }

    synchronized void put(int item) {
        while (count == slots.length) {
            try {
                wait();
            } catch (InterruptedException e) {
                // re-check the buffer state after waking up
            }
        }
        slots[tail] = item;
        tail = (tail + 1) % slots.length;
        count = count + 1;
        notifyAll();
    }

    synchronized int take() {
        while (count == 0) {
            try {
                wait();
            } catch (InterruptedException e) {
                // re-check the buffer state after waking up
            }
        }
        int item = slots[head];
        head = (head + 1) % slots.length;
        count = count - 1;
        Main.consumed[Main.consumedCount] = item;
        Main.consumedCount = Main.consumedCount + 1;
        notifyAll();
        return item;
    }
}

class Producer extends Thread {
    private Buffer buffer;
    private int[] items;

    Producer(Buffer buffer, int[] items) {
        this.buffer = buffer;
        this.items = items;
    }

    public void run() {
        for (int i = 0; i < items.length; i++) {
            buffer.put(items[i]);
        }
    }
}

class Consumer extends Thread {
    private Buffer buffer;
    private int total;

    Consumer(Buffer buffer, int total) {
        this.buffer = buffer;
        this.total = total;
    }

    public void run() {
        for (int i = 0; i < total; i++) {
            buffer.take();
        }
    }
}

