import java.util.Scanner;

public class Main {
    static int[] data;
    static int chunkSize;
    static int[] mins;
    static int[] maxs;

    static class MinMaxWorker extends Thread {
        private int index;

        MinMaxWorker(int index) {
            this.index = index;
        }

        public void run() {
            int start = index * chunkSize;
            int lo = data[start];
            int hi = data[start];
            for (int j = 1; j < chunkSize; j++) {
                int v = data[start + j];
                if (v < lo) {
                    lo = v;
                }
                if (v > hi) {
                    hi = v;
                }
            }
            mins[index] = lo;
            maxs[index] = hi;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        chunkSize = sc.nextInt();
        int n = k * chunkSize;
        data = new int[n];
        for (int i = 0; i < n; i++) {
            data[i] = sc.nextInt();
        }
        mins = new int[k];
        maxs = new int[k];
        MinMaxWorker[] workers = new MinMaxWorker[k];
        for (int i = 0; i < k; i++) {
            workers[i] = new MinMaxWorker(i);
            System.out.println("Worker " + (i + 1) + " state before start: " + workers[i].getState());
            workers[i].start();
        }
        for (int i = 0; i < k; i++) {
            workers[i].join();
        }
        int gmin = mins[0];
        int gmax = maxs[0];
        for (int i = 0; i < k; i++) {
            System.out.println("Worker " + (i + 1) + " state after join: " + workers[i].getState());
            System.out.println("Worker " + (i + 1) + " range: min " + mins[i] + " max " + maxs[i]);
            if (mins[i] < gmin) {
                gmin = mins[i];
            }
            if (maxs[i] > gmax) {
                gmax = maxs[i];
            }
        }
        System.out.println("Global min: " + gmin);
        System.out.println("Global max: " + gmax);
    }
}

