import java.util.HashMap;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] ids = new int[n];
        HashMap<Integer, Integer> count = new HashMap<>();
        for (int i = 0; i < n; i++) {
            ids[i] = sc.nextInt();
            Integer seen = count.get(ids[i]);
            if (seen == null) count.put(ids[i], 1);
            else count.put(ids[i], seen + 1);
        }
        int first = -1;
        for (int i = 0; i < n; i++) {
            if (count.get(ids[i]) == 1) {
                first = ids[i];
                break;
            }
        }
        int uniques = 0;
        for (Integer key : count.keySet()) {
            if (count.get(key) == 1) uniques++;
        }
        System.out.println(first);
        System.out.println(uniques);
    }
}

