import java.util.Scanner;

public class Main {
    static int[] distances;
    static long[] efforts;

    static class Runner extends Thread {
        private int index;

        Runner(int index) {
            super("Runner-" + (index + 1));
            this.index = index;
        }

        public void run() {
            long s = 0;
            for (int step = 1; step <= distances[index]; step++) {
                s = s + step;
            }
            efforts[index] = s;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        distances = new int[r];
        efforts = new long[r];
        for (int i = 0; i < r; i++) {
            distances[i] = sc.nextInt();
        }
        Runner[] runners = new Runner[r];
        for (int i = 0; i < r; i++) {
            runners[i] = new Runner(i);
            runners[i].start();
        }
        for (int i = 0; i < r; i++) {
            runners[i].join();
        }
        int[] order = new int[r];
        for (int i = 0; i < r; i++) {
            order[i] = i;
        }
        for (int i = 0; i < r; i++) {
            for (int j = i + 1; j < r; j++) {
                if (distances[order[j]] > distances[order[i]]) {
                    int tmp = order[i];
                    order[i] = order[j];
                    order[j] = tmp;
                }
            }
        }
        for (int i = 0; i < r; i++) {
            System.out.println("Rank " + (i + 1) + ": " + runners[order[i]].getName() + " distance " + distances[order[i]]);
        }
    }
}

