import java.util.Scanner;

public class Main {
    static void reverse(long[] a, int left, int right) {
        while(left < right) {
            long t = a[left];
            a[left] = a[right];
            a[right] = t;
            left++;
            right--;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        long[] a = new long[n];
        for(int i = 0; i < n; i++) {
            a[i] = sc.nextLong();
        }
        int kk = (int) (k % n);
        reverse(a, 0, kk - 1);
        reverse(a, kk, n - 1);
        reverse(a, 0, n - 1);
        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < n; i++) {
            if(i > 0) {
                sb.append(' ');
            }
            sb.append(a[i]);
        }
        System.out.println(sb.toString());
    }
}

