import java.util.Scanner;
import java.util.function.Function;
import java.util.function.Predicate;

interface BinOp {
    int combine(int a, int b);
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        String mapOp = sc.next();
        String filterOp = sc.next();
        String reduceOp = sc.next();

        Function<Integer, Integer> mapper;
        if (mapOp.equals("double")) {
            mapper = x -> x * 2;
        } else if (mapOp.equals("square")) {
            mapper = x -> x * x;
        } else {
            mapper = x -> x;
        }

        Predicate<Integer> filter;
        if (filterOp.equals("even")) {
            filter = x -> x % 2 == 0;
        } else if (filterOp.equals("positive")) {
            filter = x -> x > 0;
        } else {
            filter = x -> true;
        }

        BinOp reducer;
        if (reduceOp.equals("sum")) {
            reducer = (a, b) -> a + b;
        } else if (reduceOp.equals("max")) {
            reducer = (a, b) -> a > b ? a : b;
        } else {
            reducer = (a, b) -> a < b ? a : b;
        }

        int state = 0;
        boolean first = true;
        for (int i = 0; i < n; i++) {
            int mapped = mapper.apply(arr[i]);
            if (!filter.test(mapped)) {
                continue;
            }
            if (first) {
                state = mapped;
                first = false;
            } else {
                state = reducer.combine(state, mapped);
            }
        }
        if (first) {
            System.out.println("Result: empty");
        } else {
            System.out.println("Result: " + state);
        }
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            pq.add(sc.nextLong());
        }
        long total = 0;
        while (pq.size() > 1) {
            long a = pq.poll();
            long b = pq.poll();
            long merged = a + b;
            total += merged;
            pq.add(merged);
        }
        System.out.println(total);
    }
}

