import java.util.Scanner;

public class Main {
    static int[] balances;
    static int[] fromIds;
    static int[] toIds;
    static int[] amounts;

    static synchronized void doTransfer(int from, int to, int amount) {
        balances[from] = balances[from] - amount;
        balances[to] = balances[to] + amount;
    }

    static class TransferThread extends Thread {
        private int index;

        TransferThread(int index) {
            this.index = index;
        }

        public void run() {
            doTransfer(fromIds[index] - 1, toIds[index] - 1, amounts[index]);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        balances = new int[n];
        for (int i = 0; i < n; i++) {
            balances[i] = sc.nextInt();
        }
        int t = sc.nextInt();
        fromIds = new int[t];
        toIds = new int[t];
        amounts = new int[t];
        for (int i = 0; i < t; i++) {
            fromIds[i] = sc.nextInt();
            toIds[i] = sc.nextInt();
            amounts[i] = sc.nextInt();
        }
        TransferThread[] threads = new TransferThread[t];
        for (int i = 0; i < t; i++) {
            threads[i] = new TransferThread(i);
            threads[i].start();
        }
        for (int i = 0; i < t; i++) {
            threads[i].join();
        }
        for (int i = 0; i < n; i++) {
            System.out.println("Account " + (i + 1) + ": " + balances[i]);
        }
    }
}

