import java.util.Scanner;

public class Main {
    static boolean isPalindrome(String word, int left, int right) {
        if(left >= right) {
            return true;
        }
        char a = Character.toLowerCase(word.charAt(left));
        char b = Character.toLowerCase(word.charAt(right));
        if(a != b) {
            return false;
        }
        return isPalindrome(word, left + 1, right - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String word = sc.next();
        System.out.println(isPalindrome(word, 0, word.length() - 1));
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim().toLowerCase();
        int letters = 0;
        for(int i = 0; i < line.length(); i++) {
            if(Character.isLetter(line.charAt(i))) {
                letters++;
            }
        }
        char[] clean = new char[letters];
        int k = 0;
        for(int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if(Character.isLetter(c)) {
                clean[k] = c;
                k++;
            }
        }
        boolean ok = true;
        int i = 0;
        int j = clean.length - 1;
        while(i < j) {
            if(clean[i] != clean[j]) {
                ok = false;
                break;
            }
            i++;
            j--;
        }
        if(ok) {
            System.out.println("palindrome");
        } else {
            System.out.println("not a palindrome");
        }
    }
}

