import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] scores = new int[n];
        for(int i = 0; i < n; i++) {
            scores[i] = sc.nextInt();
        }
        int best = scores[0];
        for(int s : scores) {
            if(s > best) {
                best = s;
            }
        }
        int second = 0;
        boolean found = false;
        for(int s : scores) {
            if(s < best) {
                if(!found || s > second) {
                    second = s;
                    found = true;
                }
            }
        }
        if(found) {
            System.out.println(second);
        } else {
            System.out.println("No second place");
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        int c = sc.nextInt();
        int[][] a = new int[r][c];
        for(int i = 0; i < r; i++) {
            for(int j = 0; j < c; j++) {
                a[i][j] = sc.nextInt();
            }
        }
        boolean found = false;
        outer:
        for(int i = 0; i < r; i++) {
            for(int j = 0; j < c; j++) {
                boolean isRowMin = true;
                boolean isColMax = true;
                for(int k = 0; k < c; k++) {
                    if(a[i][k] < a[i][j]) {
                        isRowMin = false;
                    }
                }
                for(int k = 0; k < r; k++) {
                    if(a[k][j] > a[i][j]) {
                        isColMax = false;
                    }
                }
                if(isRowMin && isColMax) {
                    System.out.println((i + 1) + " " + (j + 1) + " " + a[i][j]);
                    found = true;
                    break outer;
                }
            }
        }
        if(!found) {
            System.out.println(-1);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        System.out.println("Value A: " + a);
        System.out.println("Value B: " + b);
        boolean over = (a > 0 && b > 0 && a > Long.MAX_VALUE - b) || (a < 0 && b < 0 && a < Long.MIN_VALUE - b);
        if(over) {
            System.out.println("Safe sum: overflow");
            System.out.println("Status: OVERFLOW");
            System.out.println("Max long: " + Long.MAX_VALUE);
        } else {
            System.out.println("Safe sum: " + (a + b));
            System.out.println("Status: OK");
        }
    }
}

