import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim();
        int words = 0;
        int vowels = 0;
        int consonants = 0;
        boolean inWord = false;
        for(int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if(c == ' ') {
                inWord = false;
            } else {
                if(!inWord) {
                    words++;
                    inWord = true;
                }
                char low = Character.toLowerCase(c);
                if(low == 'a' || low == 'e' || low == 'i' || low == 'o' || low == 'u') {
                    vowels++;
                } else {
                    consonants++;
                }
            }
        }
        System.out.println(words);
        System.out.println(vowels);
        System.out.println(consonants);
    }
}

import java.util.Scanner;

public class Main {
    static int items;
    static long processed;

    static class StageTask implements Runnable {
        public void run() {
            long s = 0;
            for (int i = 1; i <= items; i++) {
                s = s + i;
            }
            processed = s;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        int[] loads = new int[k];
        for (int i = 0; i < k; i++) {
            loads[i] = sc.nextInt();
        }
        Runnable[] pipeline = new Runnable[k];
        for (int i = 0; i < k; i++) {
            items = loads[i];
            pipeline[i] = new StageTask();
            Thread worker = new Thread(pipeline[i]);
            worker.start();
            worker.join();
            System.out.println("Stage " + (i + 1) + " done: " + processed);
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.function.Function;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<String, Function<Integer, String>> registry = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String tag = sc.next();
            String kind = sc.next();
            if (kind.equals("plain")) {
                registry.put(tag, x -> "v=" + x);
            } else if (kind.equals("hex")) {
                registry.put(tag, x -> "0x" + Integer.toHexString(x));
            } else {
                registry.put(tag, x -> Integer.toBinaryString(x));
            }
        }
        int m = sc.nextInt();
        for (int i = 0; i < m; i++) {
            String tag = sc.next();
            int value = sc.nextInt();
            Function<Integer, String> serializer = registry.get(tag);
            if (serializer == null) {
                System.out.println("Unknown type");
            } else {
                System.out.println(serializer.apply(value));
            }
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int work = n;
        int count = 0;
        while (work != 0) {
            count += work & 1;
            work >>>= 1;
        }
        int probe = n;
        int pos = -1;
        while (probe != 0) {
            probe >>>= 1;
            pos++;
        }
        boolean pow2 = n > 0 && (n & (n - 1)) == 0;
        System.out.println("Set bits: " + count);
        System.out.println("Highest position: " + pos);
        System.out.println("Power of two: " + pow2);
    }
}

