import java.util.ArrayList;
import java.util.Iterator;
import java.util.Scanner;

public class Main {

    static String joinInt(ArrayList<Integer> list) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(list.get(i));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        ArrayList<Integer> readings = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            readings.add(sc.nextInt());
        }
        int removed = 0;
        Iterator<Integer> it = readings.iterator();
        while (it.hasNext()) {
            int v = it.next();
            if (v < 0) {
                it.remove();
                removed++;
            }
        }
        System.out.println("Cleaned: " + joinInt(readings));
        System.out.println("Removed: " + removed);
    }
}

import java.util.Scanner;

public class Main {
    static int counter = 0;
    static int increments;

    static synchronized void bump() {
        counter = counter + 1;
    }

    static class CounterThread extends Thread {
        public void run() {
            for (int i = 0; i < increments; i++) {
                bump();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        increments = sc.nextInt();
        CounterThread[] threads = new CounterThread[m];
        for (int i = 0; i < m; i++) {
            threads[i] = new CounterThread();
            threads[i].start();
        }
        for (int i = 0; i < m; i++) {
            threads[i].join();
        }
        System.out.println("Final count: " + counter);
    }
}

