import java.util.Scanner;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    static int revenue = 0;
    static int passes = 0;
    static int fee;
    static int trips;
    static ReentrantLock gate = new ReentrantLock();

    static void collect() {
        gate.lock();
        try {
            revenue = revenue + fee;
            passes = passes + 1;
        } finally {
            gate.unlock();
        }
    }

    static class Car extends Thread {
        public void run() {
            for (int i = 0; i < trips; i++) {
                collect();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        trips = sc.nextInt();
        fee = sc.nextInt();
        Car[] cars = new Car[m];
        for (int i = 0; i < m; i++) {
            cars[i] = new Car();
            cars[i].start();
        }
        for (int i = 0; i < m; i++) {
            cars[i].join();
        }
        System.out.println("Total revenue: " + revenue);
        System.out.println("Vehicles served: " + passes);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        ArrayList<Integer> log = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            log.add(sc.nextInt());
        }
        ArrayList<Integer> sorted = new ArrayList<>(log);
        Collections.sort(sorted);
        ArrayList<int[]> stats = new ArrayList<>();
        int i = 0;
        while (i < sorted.size()) {
            int v = sorted.get(i);
            int j = i;
            while (j < sorted.size() && sorted.get(j) == v) {
                j++;
            }
            stats.add(new int[] { v, j - i, log.indexOf(v) });
            i = j;
        }
        Collections.sort(stats, new Comparator<int[]>() {
            public int compare(int[] a, int[] b) {
                if (a[1] != b[1]) {
                    return b[1] - a[1];
                }
                return a[2] - b[2];
            }
        });
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < k; t++) {
            if (t > 0) {
                sb.append(' ');
            }
            sb.append(stats.get(t)[0]);
        }
        System.out.println("Top: " + sb.toString());
    }
}

