import java.util.Scanner;

public class Main {
    static int[] weights;
    static long[] carried;
    static int rounds;
    static long total = 0;

    static synchronized void addWeight(int index) {
        total = total + weights[index];
        carried[index] = carried[index] + weights[index];
    }

    static class Loader extends Thread {
        private int index;

        Loader(int index) {
            this.index = index;
        }

        public void run() {
            for (int r = 0; r < rounds; r++) {
                addWeight(index);
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        rounds = sc.nextInt();
        weights = new int[m];
        carried = new long[m];
        for (int i = 0; i < m; i++) {
            weights[i] = sc.nextInt();
        }
        Loader[] loaders = new Loader[m];
        for (int i = 0; i < m; i++) {
            loaders[i] = new Loader(i);
            loaders[i].start();
        }
        for (int i = 0; i < m; i++) {
            loaders[i].join();
        }
        for (int i = 0; i < m; i++) {
            System.out.println("Loader " + (i + 1) + " carried: " + carried[i]);
        }
        System.out.println("Total weight: " + total);
    }
}

